// The fuzz-lock carry's seed and its rollback (CLOUD-2538). Run by
// `crates/batten/tests/it/renovate_carry.rs` so `test:cargo` gates it;
// `node --test .github/renovate/fuzz-lock-carry.test.mjs` runs it alone.

import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { carry, seed } from "./fuzz-lock-carry.mjs";

const REGISTRY = 'source = "registry+https://github.com/rust-lang/crates.io-index"';
const HEADER = "# This file is automatically @generated by Cargo.\nversion = 4\n";

function lock(...packages) {
  return `${HEADER}\n${packages.map((p) => `[[package]]\n${p}\n`).join("\n")}`;
}

const pkg = (name, version, source = REGISTRY) =>
  [`name = "${name}"`, `version = "${version}"`, source].filter(Boolean).join("\n");

test("the seed is the root lock, plus the harness pins the root lacks", () => {
  const root = lock(pkg("tokio", "1.53.3"), pkg("serde", "1.0.200"));
  const fuzz = lock(
    pkg("tokio", "1.53.1"),
    pkg("libfuzzer-sys", "0.4.13"),
    pkg("batten-fuzz", "0.0.0", null),
  );
  const seeded = seed(root, fuzz);
  assert.match(seeded, /name = "tokio"\nversion = "1\.53\.3"/);
  assert.doesNotMatch(seeded, /1\.53\.1/, "a shared crate takes the root's pin");
  assert.match(seeded, /name = "libfuzzer-sys"\nversion = "0\.4\.13"/, "a harness pin rides along");
  assert.doesNotMatch(seeded, /batten-fuzz/, "a path entry is cargo's to regenerate");
  assert.ok(seeded.startsWith(HEADER), "the root's header leads");
});

test("a failed resolve puts the old fuzz lock back", () => {
  const dir = mkdtempSync(join(tmpdir(), "fuzz-lock-carry-"));
  mkdirSync(join(dir, "fuzz"));
  const before = lock(pkg("tokio", "1.53.1"));
  writeFileSync(join(dir, "Cargo.lock"), lock(pkg("tokio", "1.53.3")));
  writeFileSync(join(dir, "fuzz/Cargo.lock"), before);
  assert.throws(() =>
    carry(dir, () => {
      throw new Error("index unreachable");
    }),
  );
  assert.equal(readFileSync(join(dir, "fuzz/Cargo.lock"), "utf8"), before);
});

test("a resolve that succeeds keeps the seed", () => {
  const dir = mkdtempSync(join(tmpdir(), "fuzz-lock-carry-"));
  mkdirSync(join(dir, "fuzz"));
  writeFileSync(join(dir, "Cargo.lock"), lock(pkg("tokio", "1.53.3")));
  writeFileSync(join(dir, "fuzz/Cargo.lock"), lock(pkg("tokio", "1.53.1")));
  carry(dir, () => {});
  assert.match(readFileSync(join(dir, "fuzz/Cargo.lock"), "utf8"), /1\.53\.3/);
});
